 private $db,$repo,$ind,$ev,$config,$ret,$audit,$homologacoes,$validator;public function __construct($db){$this->db=$db;$this->repo=new LancamentosRepository($db);$this->ind=new IndicadoresRepository($db);$this->ev=new EvidenciasRepository($db);$this->config=new ConfiguracoesRepository($db);$this->ret=new RetificacoesRepository($db);$this->audit=new AuditoriaRepository($db);$this->homologacoes=new HomologacoesRepository($db);$this->validator=new LancamentoValidator();}
 public function all(array $f){return $this->repo->all($f);}public function find($id,array $u){$x=$this->repo->find($id);if(!$x)throw new OutOfBoundsException('Lancamento nao encontrado.');if($u['perfil']!=='administrador'&&!AccessPolicy::scopeAllows($u,$x))throw new UnexpectedValueException('Registro fora do escopo.');return$x;}
