 public function update($id,array $i,array $u,$reason=''){$before=$this->find($id,$u);if(!LancamentoStateMachine::editable($before['status']))throw new LogicException('Lancamento submetido nao pode ser alterado.');$this->assertMutable($before);$requiresRetification=$this->pendingRetificationCycle($before);if($requiresRetification&&trim((string)$reason)==='')throw new DomainException('Justificativa obrigatoria para retificacao.');$c=$this->checked($i,$u);if($this->repo->existsForPeriod($c['indicador_id'],$c['competencia'],$id))throw new LogicException('Competencia duplicada.');$c=$this->normalizeDerivedFields($c,$before);$c['status']=$before['status'];$c['usuario_responsavel']=$u['matricula'];return$this->tx(function()use($id,$c,$before,$u,$reason,$requiresRetification){$x=$this->repo->update($id,$c);if($requiresRetification){$newVersion=max(1,(int)$before['versaoAtual']);$this->ret->create($id,$before,$x,trim((string)$reason),$u,max(1,$newVersion-1),$newVersion);if(!$this->repo->updateStatus($id,$x['status'],LancamentoStateMachine::RECTIFIED))throw new LogicException('Conflito ao concluir a retificacao.');$x=$this->repo->find($id);}$this->log('lancamento_alterado',$id,$before,$x,$u);return$x;});}
 public function deleteDraft($id,array $u){$x=$this->find($id,$u);if(!LancamentoStateMachine::deletable($x['status']))throw new LogicException('Somente rascunhos podem ser excluidos.');return$this->tx(function()use($id,$x,$u){if(!$this->repo->deleteDraft($id,LancamentoStateMachine::DRAFT))throw new RuntimeException('Conflito ao excluir rascunho.');$this->log('lancamento_excluido',$id,$x,null,$u);return true;});}
 public function submit($id,array $u){$x=$this->find($id,$u);$this->assertMutable($x);$indicator=$this->ind->find($x['indicadorId']);if(!$indicator)throw new DomainException('Indicador invalido ou inativo.');CompetenciaPeriodicidade::assertExpected($indicator,$x);$expected=LancamentoStateMachine::normalize($x['status']);if(!in_array($expected,array(LancamentoStateMachine::NOT_STARTED,LancamentoStateMachine::IN_PROGRESS,LancamentoStateMachine::DRAFT,LancamentoStateMachine::RETURNED,LancamentoStateMachine::RECTIFIED),true))throw new LogicException('Lancamento nao pode ser submetido neste estado.');if($this->requiresEvidence($x['indicadorId'])&&!$this->ev->hasCurrent($id))throw new DomainException('Anexe pelo menos um arquivo da versao atual antes de enviar para homologacao.');return$this->tx(function()use($id,$expected,$x,$u){if(!$this->repo->updateStatus($id,$x['status'],LancamentoStateMachine::SUBMITTED))throw new LogicException('Lancamento ja foi processado por outra requisicao.');$this->homologacoes->recordSubmission($id,$expected,LancamentoStateMachine::SUBMITTED,$u);$after=$this->repo->find($id);$this->log('lancamento_submetido',$id,$x,$after,$u);return$after;});}
 public function reopenPolicy($id,array$u){$x=$this->repo->find($id);if(!$x)throw new OutOfBoundsException('Lancamento nao encontrado.');if($u['perfil']!=='administrador'&&!AccessPolicy::scopeAllows($u,$x))throw new UnexpectedValueException('Registro fora do escopo.');if(LancamentoStateMachine::normalize($x['status'])!==LancamentoStateMachine::HOMOLOGATED)return array('permitida'=>false,'excepcional'=>false,'mensagem'=>'Somente lançamentos homologados podem ser reabertos.');return GovernancaHomologacao::reopenPolicy($x,$u,$this->config->get(GovernancaHomologacao::CLOSURES_KEY,array()));}
 public function mutationPolicy($id,array$u){$x=$this->find($id,$u);return GovernancaHomologacao::launchMutationPolicy($x,$this->config->get(GovernancaHomologacao::CLOSURES_KEY,array()),$this->homologacoes->exceptionalReopenCycleActive($id));}
 public function reopen($id,$reason,array $u){$reason=trim((string)$reason);if($reason==='')throw new DomainException('Justificativa obrigatoria.');if(!in_array($u['perfil'],array('administrador','homologador','consultor_diretoria'),true))throw new UnexpectedValueException('Perfil sem permissao para reabrir.');$ownsTransaction=!$this->db->inTransaction();if($ownsTransaction)$this->db->beginTransaction();try{$x=$this->repo->findForUpdate($id);if(!$x)throw new OutOfBoundsException('Lancamento nao encontrado.');if(LancamentoStateMachine::normalize($x['status'])!==LancamentoStateMachine::HOMOLOGATED)throw new LogicException('Somente lançamentos homologados podem ser reabertos.');$policy=GovernancaHomologacao::reopenPolicy($x,$u,$this->config->get(GovernancaHomologacao::CLOSURES_KEY,array()));if(empty($policy['permitida']))throw new UnexpectedValueException($policy['mensagem']);$previousVersion=max(1,(int)$x['versaoAtual']);$newVersion=$previousVersion+1;if(!$this->repo->reopenWithNextVersion($id,$x['status'],LancamentoStateMachine::REOPENED))throw new LogicException('Conflito de reabertura.');$updated=$this->repo->find($id);$action=!empty($policy['excepcional'])?'reabertura_excepcional_pos_fechamento_ca':'lancamento_reaberto';$this->homologacoes->recordDecision($id,$action,LancamentoStateMachine::HOMOLOGATED,LancamentoStateMachine::REOPENED,$reason,array('matricula'=>$u['matricula'],'perfil'=>GovernancaHomologacao::profileLabel($u['perfil'])));$this->audit->append(array('entidade'=>'lancamentos','registroId'=>$id,'acao'=>$action,'descricao'=>!empty($policy['excepcional'])?'Reabertura excepcional após fechamento para o Conselho de Administração.':'Lançamento reaberto dentro da janela de governança.','valorAnterior'=>$x,'valorNovo'=>array('lancamento'=>$updated,'indicadorId'=>$x['indicadorId'],'competencia'=>GovernancaHomologacao::launchCompetence($x),'justificativa'=>$reason,'periodoCa'=>$policy['periodo'],'dataFechamento'=>$policy['dataFechamento'],'dataReabertura'=>date('c'),'statusAnterior'=>$x['status'],'statusNovo'=>LancamentoStateMachine::REOPENED,'versaoAnterior'=>$previousVersion,'versaoNova'=>$newVersion),'usuario'=>$u['matricula'],'perfilUsuario'=>GovernancaHomologacao::profileLabel($u['perfil'])));if($ownsTransaction)$this->db->commit();return$updated;}catch(Throwable$e){if($ownsTransaction&&$this->db->inTransaction())$this->db->rollBack();throw$e;}}
 private function checked(array $i,array $u){$v=$this->validator->validate($i);if(!$v['valid'])throw new DomainException(json_encode($v['errors']));$indicator=$this->ind->find($v['data']['indicador_id']);if(!$indicator||!$indicator['ativo'])throw new DomainException('Indicador invalido ou inativo.');CompetenciaPeriodicidade::assertExpected($indicator,$v['data']);if($u['perfil']==='unidade_apuradora'&&strcasecmp($v['data']['unidade_apuradora'],$u['unidade_apuradora'])!==0)throw new UnexpectedValueException('Unidade fora do escopo.');return$v['data'];}
 private function pendingRetificationCycle(array$x){$status=LancamentoStateMachine::normalize($x['status']);if($status===LancamentoStateMachine::REOPENED)return true;if($status!==LancamentoStateMachine::IN_PROGRESS||(int)$x['versaoAtual']<=1)return false;$version=max(1,(int)$x['versaoAtual']);return$this->homologacoes->reopenCycleActive($x['id'])&&!$this->ret->existsForVersionTransition($x['id'],max(1,$version-1),$version);}
 private function normalizeDerivedFields(array$c,array$before){$indicator=$this->ind->find($c['indicador_id']);if(!$indicator)return$c;$history=$this->repo->all(array('indicadorId'=>$c['indicador_id'],'ano'=>$c['ano']));$current=array_merge($before,$c,array('id'=>$before['id']));if($indicator['tipoCalculo']==='razao_canais_digitais'){$target=$this->digitalChannelsTarget($c,$indicator);$derived=RazaoCanaisDigitaisCalculator::calculate($current,$history,$target);return$derived===null?$c:array_merge($c,$derived);}if($indicator['tipoCalculo']==='crescimento_rede_loterica_base_2025'||(int)$indicator['id']===23){$target=$this->redeLotericaTarget($c,$indicator);$derived=RedeLotericaPeriodoEquivalenteCalculator::calculate($current,$history,$target);return array_merge($c,$derived);}return$c;}
 private function digitalChannelsTarget(array$x,array$indicator){$key=sprintf('%04d-%02d',(int)$x['ano'],(int)$x['mes']);foreach($this->config->get('regrasIndicadores',array())as$rule){if((string)(isset($rule['indicadorId'])?$rule['indicadorId']:'')!==(string)$indicator['id'])continue;$params=isset($rule['parametrosCalculo'])&&is_array($rule['parametrosCalculo'])?$rule['parametrosCalculo']:array();foreach(array('metasPorCompetencia','metasMensaisPorCompetencia','metasOficiaisPorCompetencia')as$name){if(isset($params[$name][$key])&&is_numeric($params[$name][$key]))return(float)$params[$name][$key];}}if((int)$indicator['id']===8&&(int)$x['ano']===2026){$curve=array(1=>0.2770,2=>0.2829,3=>0.2805,4=>0.2803,5=>0.2798,6=>0.2798,7=>0.2815,8=>0.2827,9=>0.2837,10=>0.2859,11=>0.2878,12=>0.2911);if(isset($curve[(int)$x['mes']]))return$curve[(int)$x['mes']];}return$x['meta_referencia'];}
 private function redeLotericaTarget(array$x,array$indicator){if((int)$x['ano']===2026){$curve=array(1=>1.005,2=>1.005,3=>1.005,4=>1.010,5=>1.010,6=>1.010,7=>1.015,8=>1.015,9=>1.015,10=>1.020,11=>1.020,12=>1.020);if(isset($curve[(int)$x['mes']]))return$curve[(int)$x['mes']];}$key=sprintf('%04d-%02d',(int)$x['ano'],(int)$x['mes']);foreach($this->config->get('regrasIndicadores',array())as$rule){if((string)(isset($rule['indicadorId'])?$rule['indicadorId']:'')!==(string)$indicator['id'])continue;$params=isset($rule['parametrosCalculo'])&&is_array($rule['parametrosCalculo'])?$rule['parametrosCalculo']:array();if(isset($params['metasPorCompetencia'][$key])&&is_numeric($params['metasPorCompetencia'][$key])){$target=(float)$params['metasPorCompetencia'][$key];return$target>0&&$target<1?1+$target:$target;}}$target=$x['meta_referencia'];return is_numeric($target)&&$target>0&&$target<1?1+(float)$target:$target;}
 private function requiresEvidence($indicatorId){foreach($this->config->get('regrasIndicadores',array())as$rule){if((string)(isset($rule['indicadorId'])?$rule['indicadorId']:'')===(string)$indicatorId)return!empty($rule['exigeEvidencia']);}return false;}
 private function assertMutable(array$x){return GovernancaHomologacao::assertLaunchMutable($x,$this->config->get(GovernancaHomologacao::CLOSURES_KEY,array()),$this->homologacoes->exceptionalReopenCycleActive($x['id']));}
 private function log($a,$id,$b,$n,array$u){$this->audit->append(array('entidade'=>'lancamentos','registroId'=>$id,'acao'=>$a,'descricao'=>'Operacao no modulo de lancamentos.','valorAnterior'=>$b,'valorNovo'=>$n,'usuario'=>$u['matricula'],'perfilUsuario'=>$u['perfil']));}
